:root{
  --stage:#d9d7cf; --stage-grid:#cbc9c1; --stage-ink:#4a4740; --stage-mute:#6f6b62;
  --marker:'851 GBai Marker','Segoe UI',system-ui,sans-serif;
}
@media (prefers-color-scheme: dark){ :root:not([data-theme="light"]){ --stage:#17171a; --stage-grid:#232327; --stage-ink:#c9c5bc; --stage-mute:#8d8a83; } }
:root[data-theme="dark"]{ --stage:#17171a; --stage-grid:#232327; --stage-ink:#c9c5bc; --stage-mute:#8d8a83; }

*{box-sizing:border-box}
body{margin:0;background:var(--stage);color:var(--stage-ink);font-family:'Segoe UI',system-ui,-apple-system,sans-serif;
  -webkit-font-smoothing:antialiased;
  background-image:radial-gradient(circle at 1px 1px,var(--stage-grid) 1px,transparent 0);background-size:26px 26px;}
/* 375 x 812 screen, coordinates follow the Figma frame; sized and scaled by .app-screen like the editor */
.screen{position:relative;width:375px;height:812px;overflow:hidden;background:#ececea;
  user-select:none;-webkit-user-select:none}
.screen{touch-action:pan-y}
.screen img{-webkit-user-drag:none;user-drag:none}
.screen.dragging,.screen.dragging .bk{cursor:grabbing}
.abs{position:absolute;display:block;max-width:none}
/* fixed chrome must out-rank a fully open book (.bk z-index tops out at 11) so scrolled shelf content never covers the header or nav */
#title,#bell,.hdrBack,.navBack,#nav{z-index:20}
#title{left:63px;top:73px;width:297px;height:52px;pointer-events:none}
#bell{left:326px;top:80px;width:34px;height:34px;border:0;background:none;padding:0;cursor:pointer;border-radius:50%}
#bell:focus-visible,.bk:focus-visible{outline:2px solid #2f6bf2;outline-offset:3px}
.hdrBack{position:absolute;left:0;top:0;width:375px;height:115px;background:#ececea;pointer-events:none}
.navBack{position:absolute;left:0;top:718px;width:375px;height:94px;background:#ececea;pointer-events:none}
/* the shelves scroll vertically as new ones are added; horizontal carousel drags stay JS-driven (touch-action lets both coexist) */
#shelvesWrap{position:absolute;inset:0;overflow-y:auto;overflow-x:hidden;touch-action:pan-y;-webkit-overflow-scrolling:touch;overscroll-behavior:contain;scrollbar-width:none}
#shelvesWrap::-webkit-scrollbar{display:none}
#shelvesInner{position:relative;width:375px;height:812px}
#line1{left:0;top:407px;width:375px;height:10px;pointer-events:none}
#line2{left:0;top:692px;width:375px;height:11.3px;pointer-events:none}
#row2{position:absolute;inset:0;pointer-events:none}

/* ---------- 3D book row ---------- */
#row{position:absolute;inset:0;pointer-events:none}
.spineTxt{position:absolute;inset:0;display:flex;align-items:center;justify-content:center}
.spineTxt span{writing-mode:vertical-rl;transform:rotate(180deg);font-family:var(--marker);font-size:15px;letter-spacing:1px;white-space:nowrap}
.bk{position:absolute;left:0;pointer-events:auto;cursor:pointer;transform-style:preserve-3d;transform-origin:0 50%;will-change:transform;
  -webkit-tap-highlight-color:transparent}
.face{position:absolute;top:0;backface-visibility:hidden;-webkit-backface-visibility:hidden}
.spine{background-repeat:no-repeat;background-size:100% 100%}
.str{position:absolute;left:-1.84px;top:-3.96px;width:20.33px;height:142.67px;pointer-events:none}
.back{left:0;border-radius:8px}
.cover{left:0}
.cimg{position:absolute;inset:0;width:100%;height:100%;display:block}
.ccss{position:absolute;inset:0;background:var(--c);border-radius:0 8px 8px 0;overflow:hidden}
.ccss .art{position:absolute;left:7.7%;right:6.8%;top:14%;height:54%;border-radius:9px;
  background:
    radial-gradient(ellipse 20% 20% at 30% 30%, #b9c3ce 0 62%, transparent 66%),
    radial-gradient(ellipse 24% 22% at 52% 52%, #8a9caa 0 62%, transparent 66%),
    radial-gradient(ellipse 16% 24% at 80% 42%, #c4ccd5 0 62%, transparent 66%),
    #f3f0e9}
.ccss .ttl{position:absolute;left:15.7px;top:70.3%;font-family:var(--marker);font-size:20px;line-height:24px;white-space:nowrap;color:var(--tc)}
.ccss .dots{position:absolute;left:15px;bottom:5px;display:flex}
.ccss .dots i{width:19px;height:19px;border-radius:50%;background:var(--tc);border:2.5px solid #f6f3ec;margin-right:-7px}
/* per-book delete / edit controls — real tappable buttons, only reachable once the book is open (the .cover face
   isn't front-facing otherwise) and additionally faded so they don't linger during the leaning<->standing transition */
.trashBtn{position:absolute;right:3px;bottom:3px;width:30px;height:30px;padding:0;border:0;background:none;cursor:pointer;opacity:0;transition:opacity .15s;-webkit-tap-highlight-color:transparent}
.trashBtn img{position:absolute;left:6px;top:6px;width:18px;height:18px}
.editBtn{position:absolute;right:1px;top:4px;width:30px;height:30px;padding:0;border:0;background:none;cursor:pointer;-webkit-tap-highlight-color:transparent}
.editBtn .sl{position:absolute;right:8px;top:8px;width:14px}
.editBtn:focus-visible,.trashBtn:focus-visible{outline:2px solid #2f6bf2;outline-offset:2px;border-radius:6px}

/* shared modal for delete-confirm and edit-notebook, dimming the whole screen */
#modalRoot{position:absolute;inset:0;z-index:40;pointer-events:none}
.modalBack{position:absolute;inset:0;background:rgba(20,18,14,.4);display:flex;align-items:center;justify-content:center;pointer-events:auto}
.modalCard{width:280px;max-width:calc(100% - 40px);background:#f6f3ec;border-radius:16px;padding:18px 20px 16px;
  box-shadow:0 18px 40px -12px rgba(0,0,0,.5);font-family:'Segoe UI',system-ui,sans-serif}
.modalCard h3{margin:0 0 6px;font-family:var(--marker);font-size:19px;font-weight:400;color:#1d1c18}
.modalCard p{margin:0 0 14px;font-size:12.5px;color:#8b867c;line-height:1.5}
.mLabel{display:block;font-size:11px;letter-spacing:.5px;color:#8b867c;margin:12px 0 6px;text-transform:uppercase}
.mInput{width:100%;box-sizing:border-box;border:1px solid #d8d3c6;border-radius:9px;padding:9px 11px;font-family:var(--marker);font-size:16px;background:#fff;color:#1d1c18}
.mInput:focus{outline:2px solid #2f6bf2;outline-offset:1px}
.swatches{display:flex;gap:9px;flex-wrap:wrap}
.swatch{width:28px;height:28px;border-radius:50%;border:2.5px solid transparent;cursor:pointer;padding:0}
.swatch.on{border-color:#1d1c18}
.coverPick{display:flex;gap:12px;align-items:center}
.coverPreview{position:relative;overflow:hidden;width:56px;height:56px;border-radius:10px;background:#fff no-repeat center/cover;
  border:1.5px dashed #d8d3c6;flex:0 0 auto}
.coverPreview.empty{background-image:none!important}
.coverPreview.empty::after{content:'';position:absolute;inset:0;background:
    radial-gradient(ellipse 26% 26% at 32% 34%, #b9c3ce 0 60%, transparent 64%),
    radial-gradient(ellipse 30% 28% at 55% 55%, #8a9caa 0 60%, transparent 64%),
    radial-gradient(ellipse 22% 30% at 78% 42%, #c4ccd5 0 60%, transparent 64%),
    #f3f0e9}
.coverPickBtns{display:flex;flex-direction:column;gap:6px;flex:1}
.mUpload,.mRemoveCover{border:0;border-radius:16px;padding:7px 12px;font-family:'Segoe UI',system-ui,sans-serif;font-size:12.5px;cursor:pointer;text-align:center}
.mUpload{background:#171a16;color:#fff}
.mRemoveCover{background:#e7e2d4;color:#8b4a3f}
.modalBtns{display:flex;gap:10px;margin-top:18px}
.modalBtns button{flex:1;border:0;border-radius:22px;padding:10px 0;font-family:var(--marker);font-size:15px;cursor:pointer}
.mCancel{background:#e7e2d4;color:#1d1c18}
.mSave{background:#171a16;color:#fff}
.mDanger{background:#b53a2f;color:#fff}
.trash{position:absolute;width:18px;height:18px;pointer-events:none}

/* bottom navigation: four 51px icons, two states each (black disc = not selected, brush ring on cream = selected) */
#nav{position:absolute;left:0;top:0;width:375px;height:0}
.nv{position:absolute;top:731px;width:51px;height:51px;padding:0;border:0;background:none;cursor:pointer;border-radius:50%;
  -webkit-tap-highlight-color:transparent;transition:transform .14s cubic-bezier(.3,.8,.3,1)}
.nv:active{transform:scale(.93)}
.nv:focus-visible{outline:2px solid #2f6bf2;outline-offset:4px}
.nv img{position:absolute;max-width:none;pointer-events:none;transition:opacity .22s}
.nv .on{opacity:0}
.nv[aria-pressed="true"] .on{opacity:1}
.nv[aria-pressed="true"] .off{opacity:0}
@media (prefers-reduced-motion:reduce){ .nv,.nv img{transition:none} }
.toast{position:absolute;left:50%;bottom:96px;transform:translateX(-50%) translateY(14px);background:#171a16;color:#fff;
  font-family:var(--marker);font-size:14px;padding:9px 18px;border-radius:20px;opacity:0;transition:.28s;pointer-events:none;z-index:80;white-space:nowrap}
.toast.show{opacity:1;transform:translateX(-50%) translateY(0)}

/* notebook search: same card as the edit/delete dialogs, anchored under the header instead of centred */
.searchBack{align-items:flex-start;padding-top:96px}
.searchCard{width:315px;padding:14px}
.searchInput{font-size:15px}
.searchResults{display:flex;flex-direction:column;gap:2px;margin-top:10px;max-height:420px;overflow-y:auto}
.searchHit{display:flex;align-items:center;gap:10px;width:100%;padding:9px 10px;border:0;border-radius:10px;background:transparent;
  text-align:left;cursor:pointer;font-family:var(--marker);font-size:15px;color:#1d1c18}
.searchHit:hover,.searchHit:focus-visible{background:#ece7da;outline:none}
.searchHit i{flex:none;width:12px;height:22px;border-radius:3px}
.searchHit span{flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.searchHit small{flex:none;font-size:11px;color:#8b867c}
.searchEmpty{margin:14px 0 6px;text-align:center;color:#8b867c;font-size:13px}
/* time tab: every notebook's time capsules */
.capsuleListCard h3{margin:2px 4px 2px;font-size:18px}
.capsuleHit span{display:flex;flex-direction:column;gap:3px}
.capsuleHit b{font-weight:400;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.capsuleHit span small{font-size:11px;color:#8b867c;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.capsuleHit em{flex:none;padding:4px 8px;border-radius:999px;background:#1e2026;color:#fff;font-style:normal;font-size:11px;font-family:var(--marker)}
.capsuleHit.isOpen em{background:#efe7db;color:#1e2026}
.capsuleListCard .searchEmpty{line-height:1.7}
/* settings tab */
.settingsCard{padding:16px 18px 14px}
.settingsCard h3{margin:0 0 4px;font-size:18px}
.setSec{padding:12px 0;border-bottom:1px solid #e4dfd2}
.setSec:last-of-type{border-bottom:0}
.setSec h4{margin:0 0 5px;font-family:var(--marker);font-size:14px;font-weight:400;color:#1d1c18}
.settingsCard .setSec p{margin:0 0 9px;font-size:12px;line-height:1.55;color:#8b867c}
.settingsCard .setSec p.setUsage{color:#5d594f}
.setBtns{display:flex;gap:8px}
.setBtn{flex:1;border:0;border-radius:18px;padding:8px 0;background:#e7e2d4;color:#1d1c18;font-family:var(--marker);font-size:14px;cursor:pointer}
.setBtn.isDark{background:#171a16;color:#fff}
.setBtn.isDanger{background:transparent;color:#b53a2f;box-shadow:inset 0 0 0 1.5px #b53a2f}
.setBtn:disabled{opacity:.45;cursor:default}
.settingsCard p.setAbout{margin:8px 0 0;text-align:center;font-size:11px;color:#b1ac9f}
/* ---------- shelf popups wear the editor's word/sentence sheet: paper panel art, marker type, × close ---------- */
.modalBack{background:rgb(36 34 34 / 26%)}
.modalCard{box-sizing:border-box;width:315px;padding:20px;border-radius:0;box-shadow:none;color:#242222;font-family:var(--marker);font-size:12.5px;
  background:url("/icons/panel-top.svg") top / 100% 20px no-repeat,url("/icons/panel-bottom.svg") bottom / 100% 20px no-repeat,url("/icons/panel-middle.svg") 0 19px / 100% calc(100% - 38px) no-repeat;
  filter:drop-shadow(0 -8px 24px rgb(36 34 34 / 18%))}
.modalCard h3{margin:0 0 14px;font-size:17px;line-height:24px;color:#242222}
.modalCard p{font-size:12.5px;color:#7d7a74}
.mLabel{font-family:var(--marker);text-transform:none;letter-spacing:0}
.sheetWrap{position:relative;max-width:calc(100% - 16px)}
.sheetWrap > .modalCard{max-width:100%}
.sheetClose{position:absolute;top:20px;right:20px;z-index:3;width:20px;height:20px;padding:0;border:0;background:transparent;color:#1e2026;font:24px/18px var(--marker);cursor:pointer}
.sheetClose:focus-visible{outline:2px solid #3465d6;outline-offset:2px}
/* search field: the same drawn field and magnifier as the word panel */
.sheetSearch{position:relative;display:block;height:31px;padding:0 12px;background:url("/icons/search-field.svg") center / 100% 31px no-repeat}
.sheetSearch::after{content:"";position:absolute;top:6px;right:9px;width:19px;height:19px;background:url("/icons/search.svg") center / contain no-repeat;pointer-events:none}
.sheetSearch .searchInput{box-sizing:border-box;width:100%;height:31px;padding:0 28px 0 0;border:0;background:transparent;color:#242222;font:14px var(--marker);outline:none;-webkit-appearance:none;appearance:none}
.sheetSearch .searchInput::-webkit-search-cancel-button{display:none}
/* result rows: the sentence-library rows */
.searchCard .searchResults{gap:7px;margin-top:12px}
.searchCard .searchHit{padding:10px 14px;border-radius:14px;background:#ecedf0;color:#1e2026;font:14px/20px var(--marker)}
.searchCard .searchHit:hover,.searchCard .searchHit:focus-visible{background:#ecedf0;outline:2px solid #3465d6;outline-offset:-2px}
.searchCard .searchHit small,.capsuleHit span small{font-family:var(--marker);color:#8b8a86}
.searchCard .searchEmpty{font-family:var(--marker);color:#8b8a86}
.capsuleListCard h3,.settingsCard h3{margin:0 0 14px;font-size:17px}
/* settings */
.settingsCard{padding:20px}
.setSec{border-bottom-color:#ecedf0}
.setSec h4{font-size:14px;color:#242222}
.settingsCard .setSec p{font-family:var(--marker);color:#7d7a74}
.setBtn{background:#ecedf0;border-radius:14px}
.setBtn.isDark{background:#1e2026}
.modalBtns button{border-radius:14px}
.mCancel{background:#ecedf0}
.mSave{background:#1e2026}
/* app title (was the "BETWEEN LINES / MY NOTEBOOKS" artwork) */
#title{display:flex;flex-direction:column;align-items:center;justify-content:center;margin:0;font-weight:400;color:#1d1c18}
#title strong{font-family:var(--marker);font-size:36px;font-weight:400;line-height:38px;letter-spacing:6px}
#title span{margin-top:3px;font-family:var(--marker);font-size:11px;line-height:13px;letter-spacing:3px;color:#3b3a36}
/* collaborator avatars on a shared notebook's cover */
.dots i{background-color:#fdfdfb;background-size:cover;background-position:center}
.coverDots{position:absolute;left:11px;bottom:12px;display:flex;z-index:1}
.coverDots i{width:23px;height:23px;border-radius:50%;border:2.5px solid #f6f3ec;margin-right:-9px;background-color:#fdfdfb;background-size:cover;background-position:center}
/* custom colour: a rainbow swatch wrapping the native colour picker; shows the picked colour once set */
.swatchCustom{position:relative;display:block;overflow:hidden;background:conic-gradient(#e0632c,#f6be45,#3d8a4f,#1f9c96,#3a4f84,#8a5cb0,#c8577a,#e0632c)}
.swatchCustom::after{content:"+";position:absolute;inset:0;display:grid;place-items:center;color:#fff;font:600 15px/1 system-ui,sans-serif;text-shadow:0 0 3px rgb(0 0 0 / 45%);pointer-events:none}
.swatchCustom.isSet::after{content:none}
.swatchCustom input{position:absolute;inset:0;width:100%;height:100%;opacity:0;cursor:pointer;border:0;padding:0}
/* keep the title inside the 115px header backing, so a shelf line scrolled up under it never shows through */
#title{top:62px;height:48px}
#title strong{font-size:34px;line-height:34px}
/* room for the custom-colour swatch on the same row */
.swatches{gap:6px}
/* empty second shelf: an invitation to make your own notebook */
.ownHint{position:absolute;left:50%;width:250px;height:120px;transform:translateX(-50%);display:flex;flex-direction:column;align-items:center;justify-content:center;gap:8px;border:2px dashed #b9b4a8;border-radius:16px;background:transparent;color:#5d594f;font-family:var(--marker);cursor:pointer;z-index:1}
.ownHint strong{font-size:17px;font-weight:400;color:#1d1c18}
.ownHint span{font-size:12px}
.ownHint[hidden]{display:none}
